"use strict";
let P, cnv;
function setup() 
{		
		cnv = createCanvas(windowWidth, windowHeight, WEBGL);
		noStroke();

		P = new p5.Shader(cnv,vs,fs);

		shader(P);
	  P.setUniform("RR", [width, height]);
};

function draw() 
{
		clear();

    P.setUniform("time", millis() * .001);

		push();

		rotateX(1.7);
    rotateZ(PI * ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width));
    rotateY(PI * ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / height));

		P.setUniform("M",  cnv.uMVMatrix['mat4'] );

		pop();

    plane(1, 1, 32, 32);
};

let count = 0;
function mouseWheel(event) 
{
		count += .05 * event.delta;
		P.setUniform("zoom", count);
};

// ^;.;^

// === Tab: vs ===
const vs = `attribute vec3 aPosition;
uniform mat4 M; 
uniform float time, zoom;

varying vec2 N; 

void main() 
{

	vec3 p = mat3(M) * aPosition;

	// time
	float t = time * .81;

	#define wave(p, d, f, s)(exp(1.0 - sin(length(cross(d, p)) / length(d) * f + s)))

	// wave equation parameters
  // position direction frequency speed 
	float f = wave(p.xyz * mod(time * .25, 4.), vec3(0, 0, 1.0001), 10.0, t);

	float amplitude = 0.051;
	p.y += log(f) / log(amplitude); // displace on the y axis

	gl_Position = vec4(p, 1.2 + zoom);

	N = -aPosition.xy;

}`;

// === Tab: fs ===
const fs = `precision highp float; 
varying vec2 N; 
uniform float time; 
uniform vec2 RR; 

void main() 
{

	float asp = min(RR.x, RR.y) * .05;

	gl_FragColor.rgb = 1.7 - sqrt(vec3(.8 / abs(sin(time * 2. + N.x * asp) + cos(time * .2 + N.y * asp))));
	gl_FragColor.a = 1.;

}`;

